let frontmatter = {
    "title": "The Future of Fumadocs MDX",
    "description": "A roadmap for Fumadocs MDX.",
    "author": "Fuma Nama",
    "date": new Date(1764892800000)
};
let lastModified = new Date(1767094652000);
let structuredData = {
    "contents": [
        {
            "heading": "overview-of-fumadocs-mdx",
            "content": "Fumadocs MDX serves as a content processing layer, initially developed for processing MDX files and as an alternative to Contentlayer."
        },
        {
            "heading": "overview-of-fumadocs-mdx",
            "content": "Its primary functions include:"
        },
        {
            "heading": "overview-of-fumadocs-mdx",
            "content": "Compiling and processing content."
        },
        {
            "heading": "overview-of-fumadocs-mdx",
            "content": "Offering interfaces to access compiled content."
        },
        {
            "heading": "overview-of-fumadocs-mdx",
            "content": "Ensuring type safety and compatibility across environments, such as browsers and Cloudflare Workers."
        },
        {
            "heading": "comparison-with-cms",
            "content": "Fumadocs MDX is not a content management system (CMS). A CMS encompasses more than content processing, it integrates features such as:"
        },
        {
            "heading": "comparison-with-cms",
            "content": "Database Integration: For storing content."
        },
        {
            "heading": "comparison-with-cms",
            "content": "Version Control: To enable rollbacks, commits, and conflict resolution."
        },
        {
            "heading": "comparison-with-cms",
            "content": "Permission Management: To handle user access and roles."
        },
        {
            "heading": "comparison-with-cms",
            "content": "Authoring Workflow: Supporting stages like drafting, reviewing, and publishing."
        },
        {
            "heading": "comparison-with-cms",
            "content": "Fumadocs MDX lacks these CMS capabilities independently, but they can be achieved through integration with Git and GitHub. This approach offers distinct benefits over traditional CMS solutions, including:"
        },
        {
            "heading": "comparison-with-cms",
            "content": "Maintaining a unified history within Git, rather than distributing it across Git and a separate CMS."
        },
        {
            "heading": "comparison-with-cms",
            "content": "Composing content and code changes in a single pull request."
        },
        {
            "heading": "comparison-with-cms",
            "content": "GitHub's collaboration tools, such as access controls, pull request reviews, and automation, support the implementation of authoring workflows."
        },
        {
            "heading": "comparison-with-cms",
            "content": "Fumadocs MDX is not intended to evolve into a CMS; it remains a foundational content processing layer."
        },
        {
            "heading": "roadmap",
            "content": "Fumadocs MDX is closely associated with Fumadocs, yet the content processing layer should ideally operate independently, without reliance on any specific documentation framework."
        },
        {
            "heading": "roadmap",
            "content": "title: Note"
        },
        {
            "heading": "roadmap",
            "content": "At present, Fumadocs MDX depends solely on the remark and rehype plugins from fumadocs-core."
        },
        {
            "heading": "roadmap",
            "content": "In the near future, certain components will transition to fuma-content, improving extensibility and introducing more APIs. Such as:"
        },
        {
            "heading": "roadmap",
            "content": "Framework Agnostic: Fuma Content should work anywhere, including Vite, Turbopack/Webpack, and even JS runtimes."
        },
        {
            "heading": "roadmap",
            "content": "No Framework Defaults: the MDX preset of Fumadocs will be offered by fumadocs-core, likely as a Fuma Content plugin."
        },
        {
            "heading": "roadmap",
            "content": "Content Adapters: Expanding support beyond MDX and JSON files to include custom collection types, as well as an Obsidian plugin for handling editor-specific syntax."
        },
        {
            "heading": "roadmap",
            "content": "Zero breaking changes to Fumadocs MDX: we adopt Fuma Content under the hood, but surface APIs will not be changed. Ideally, it will be similar to how Vite leverages Rolldown."
        },
        {
            "heading": "roadmap",
            "content": "API-wise, Fuma Content plugins will distinguish from bundler plugins, but plugins can leverage the built-in abstraction layer to implement loaders.\nOtherwise, we will encourage Unplugin for advanced needs."
        },
        {
            "heading": "roadmap",
            "content": "Although fuma-content focuses on content processing, it provides a foundation for developing a CMS layer, such as plugins for MDX editing or remote databases. It will be a bigger goal."
        },
        {
            "heading": "roadmap",
            "content": "title: Clarification"
        },
        {
            "heading": "roadmap",
            "content": "type: warn"
        },
        {
            "heading": "roadmap",
            "content": "Fumadocs MDX extends beyond a simple MDX loader, its architecture supports multiple formats."
        },
        {
            "heading": "roadmap",
            "content": "Although no renaming is planned, the name Fumadocs MDX no longer fully captures its scope."
        },
        {
            "heading": "the-current-progress",
            "content": "Fumadocs MDX already includes primitives for advanced setups, such as the new Workspace API, which enables content processing across multiple repositories."
        },
        {
            "heading": "the-current-progress",
            "content": "We are welcome for feedbacks on GitHub Discussions!"
        }
    ],
    "headings": [
        {
            "id": "overview-of-fumadocs-mdx",
            "content": "Overview of Fumadocs MDX"
        },
        {
            "id": "comparison-with-cms",
            "content": "Comparison with CMS"
        },
        {
            "id": "roadmap",
            "content": "Roadmap"
        },
        {
            "id": "the-current-progress",
            "content": "The Current Progress"
        }
    ]
};
